import {extendedHints} from './hints-extended.js';
// Shared methods are references, not automatically assigned solutions.
const method=(topic,title,recognize,steps,mistake,example,subtopic=topic)=>({topic,subtopic,title,recognize,steps,mistake,example});
export const techniques=[
  method('因式分解','抽公因式','每一項都有相同的乘數，例如 6x² 和 9x 都有 3x。',['先看數字：找一個能整除每項數字的最大整數。','再看字母：每項都有的才可抽出；例如 x² 和 x 共同有一個 x。','把共同部分寫在括號外，其餘留在裏面。最後乘回去，應得到原式。'],'抽出 3x 後，括號內每一項都要除以 3x；原本的負號也要保留。','6x² − 9x：兩項都除以 3x，分別剩下 2x 和 3，所以是 3x(2x − 3)。'),
  method('因式分解','平方差與完全平方','留意 9、x² 這類「一個數或式子乘自己」的部分。',['只有兩個平方相減時，用 A² − B² = (A + B)(A − B)，一個括號加、一個減。','有三項時，先看頭尾是否是 A²、B²，再看中間是否是 2AB 或 −2AB。','三項都吻合，才可寫成 (A + B)² 或 (A − B)²。乘回去檢查中間那項。'],'兩個平方相加不能用平方差；也不能只看頭尾，就認定三項能合成一個平方。','x² + 6x + 9：9 = 3²，而 6x = 2 × x × 3，所以是 (x + 3)²。'),
  method('因式分解','二次三項式','式子有 x²、x 和一個沒有 x 的數，例如 x² + 5x + 6。',['先看每項有沒有共同乘數，有的話先抽出。再寫成 ax² + bx + c。','找兩個數：相乘等於 a × c，相加等於 b。用它們把中間的 bx 拆成兩項。','把四項分成兩組，各自抽出共同乘數，再找兩組相同的括號。乘回去核對。'],'正負號也要一起試；找到的兩數必須同時符合「相乘」和「相加」兩個條件。','x² + 5x + 6：2 × 3 = 6，2 + 3 = 5，所以可寫成 (x + 2)(x + 3)。'),
  method('因式分解','分組與利用前題','後一小題裏出現前一小題的式子，或幾項可以分組處理。',['圈出與前題相同的部分。','把圈起的部分換成前題答案；其他項再找共同乘數，寫成括號。','兩邊若有一模一樣的括號，把它當成一整個共同乘數抽出。'],'前面若有減號，表示減去整個括號，不是只改括號內第一項的符號。','x² − 4 + 3x − 6 = (x − 2)(x + 2) + 3(x − 2)。兩部分都有 (x − 2)，所以是 (x − 2)(x + 5)。'),
  method('面積與體積','拆分平面圖形','面積是圖形佔了多大一塊地方。複雜圖形可以先拆成幾個熟悉的小圖形。',['在圖上畫線，把它分成三角形、長方形等；先把所有長度換成相同單位。','套用各部分的面積公式。三角形和梯形的高，要與所選底邊成直角，不能隨便用斜邊。','需要的部分相加；挖走或不要的部分扣掉。答案用 cm² 等平方單位。'],'同一塊重疊的地方只計一次；每次代公式前，看看所用的高是否真的垂直。','梯形上下底 4、8，高 3：先加兩底，再乘高除以 2，面積 = (4 + 8) × 3 ÷ 2 = 18。','面積'),
  method('面積與體積','底面積與垂直高','體積是立體佔了多少空間，不是外面那層的面積。',['先找底面，算它的面積；再找與底面成直角的高。','柱體的體積是「底面積 × 高」；同底同高的錐體只有它的 1/3，所以還要除以 3。','有空心部分就扣走那部分體積；答案用 cm³ 等立方單位。'],'沿斜面量到的長度不是垂直高。錐體公式也別漏掉除以 3。','圓柱半徑 2、高 5：底面積 = π × 2²，體積 = π × 2² × 5 = 20π。','體積'),
  method('面積與體積','列清外露表面','求物件外面整層的面積，或做一個容器要用多少材料。',['先列出要計的每個面，例如無蓋圓柱只有一個圓底和旁邊的曲面。','各個面分開算。圓錐旁邊的曲面用 πrl，r 是底面半徑，l 是沿側面由頂點到底邊的斜高。','把需要的面加起來，答案用 cm²。若先算了兩件物件的全部表面，貼合藏起來的面就要扣回。'],'只計需要的表面；不要把藏在裏面的接合面算進去，也不要用體積公式。','無蓋圓柱半徑 2、高 5：旁邊曲面 2π × 2 × 5，加一個圓底 π × 2²，共 24π。','表面積'),
  method('直線坐標幾何','斜率與直線','已知直線上的兩點，或題目說兩條線平行、成直角。',['斜率是「向上改變多少 ÷ 向右改變多少」：用 (y₂ − y₁)/(x₂ − x₁)。','平行線的斜率相同。兩條線若都有斜率，成直角時，兩個斜率相乘等於 −1。','要求直線方程，可把斜率 m 和一點 (x₁,y₁) 放進 y − y₁ = m(x − x₁)。'],'直上直下的線，兩點的 x 相同，不能除以 0，所以沒有斜率；上面的乘法規則不適用。','經過 (1,2)，斜率是 3：把 x₁ = 1、y₁ = 2、m = 3 代入，得 y − 2 = 3(x − 1)。'),
  method('二次方程','整理為零再求根','方程有 x²，而且沒有 x³ 等更高次方。求根就是找出符合方程的 x。',['把所有項移到同一邊，另一邊變成 0。','試寫成兩個括號相乘等於 0，再讓每個括號分別等於 0；不能分解時可用求根公式。','每個算出的 x 都要代回檢查。若 x 代表長度，0 和負數就不能用。'],'只有乘積等於 0，才可說其中一個括號等於 0；例如乘積等於 6 時不能這樣做。','(x − 2)(x − 3) = 0：x − 2 = 0 或 x − 3 = 0，所以 x = 2 或 3。'),
  method('二次方程','判別式與等根','題目問有多少個實數答案，或說有「等根」，即兩個答案相同。',['整理成 ax² + bx + c = 0，找出 a、b、c，包括它們的正負號；a 不能是 0。','算 b² − 4ac，這叫判別式。結果等於 0：等根；大於 0：兩個不同的實數答案。','結果小於 0：沒有實數答案。若用這條件求未知數，算完要代回檢查 a 仍不等於 0。'],'題目若要求兩個不同答案，必須大於 0，不能把等於 0 也包括。','x² + 4x + c = 0 要有等根，就列 4² − 4 × 1 × c = 0。'),
  method('相似形','先找對應邊','形狀相同，只是整個放大或縮小，就可用分數比較大小。A/B 表示「A 除以 B」。',['先找相同位置的邊，這些叫「對應邊」。例如 A 的邊長 / B 的對應邊長 = 2/3。','面積比是邊長比的二次方：A 的面積 / B 的面積 = (2/3)² = 4/9。即 A 的面積是 B 的 4/9。','相似立體的體積比是邊長比的三次方：A 的體積 / B 的體積 = (2/3)³ = 8/27。'],'必須是相似圖形或相似立體才可用；分子、分母的次序要一致。球與圓柱不相似，不能直接這樣比較。','(2/3)² 就是 (2/3) × (2/3)；(2/3)³ 則再乘一次 (2/3)。相似立體的表面面積也用二次方。'),
  method('畢氏定理','辨認斜邊','題目已知三角形有一個 90° 角，或給了三邊，要你檢查是否有直角。',['直角對面的邊最長，叫斜邊，記作 c；另兩邊記作 a、b。','已知直角時，用 a² + b² = c²。要檢查是否直角，就看兩條較短邊的平方和，是否等於最長邊的平方。','算出的是長度平方時，還要開平方根，並取正數。再檢查斜邊是否仍最長。'],'√(a² + b²) 不等於 a + b；圖畫得像直角，也不代表題目已給直角。','兩短邊 6、8：6² + 8² = 100，斜邊要再開根，所以是 10，不是 100。'),
  method('圓的坐標幾何','配方找圓心','題目給圓的方程，要找圓心、半徑，或判斷一點與圓的位置。',['目標是寫成 (x − a)² + (y − b)² = r²；這樣圓心就是 (a,b)，半徑就是 r。','把 x 和 y 的部分各自湊成平方。例如 x² + 6x = (x + 3)² − 9，補了 9 就要減回 9。','整理後讀出圓心，右邊的數再開平方根，才是半徑。半徑平方要大於 0，才是一個真正的圓。'],'(x + 3)² 代表圓心的 x 是 −3；右邊若是 25，半徑是 5，不是 25。','(x − 2)² + (y + 1)² = 9：圓心是 (2,−1)，半徑 √9 = 3。'),
  method('指數與對數','整數與負指數','字母右上角有次方，例如 x³；有些次方前面有負號，例如 x⁻²。',['先算括號外的次方：(x²)³ 把 2 × 3；(xy)³ 裏的 x 和 y 都要取三次方。','再合併相同字母：相乘就把次方相加，相除就相減。例如 x⁵ ÷ x² = x³。','次方若是負數，改寫成分數：x⁻² = 1/x²，x 不能是 0。'],'負次方不代表答案是負數；x⁻² 不是 −x²。不同底數也不能直接加減次方。','x³ ÷ x⁵：先算 3 − 5 = −2，再把 x⁻² 寫成 1/x²，其中 x ≠ 0。','指數'),
  method('指數與對數','分數指數與根式','正數的次方是分數，例如 16^(3/4)，這不是把 16 乘 3/4。',['a > 0 時，a^(m/n) 的分母 n 表示開 n 次根，分子 m 表示取 m 次方。','通常先開根較容易，例如 16^(3/4) 先找哪個數的四次方是 16。','再取分子指定的次方；如果整個次方是負數，最後用 1 除以算出的結果。'],'以上用正底數 a。不要把負底數直接套進所有分數次方規則。','16^(3/4)：2⁴ = 16，所以先得 2，再算 2³ = 8；16^(−3/4) 則是 1/8。','指數'),
  method('指數與對數','同底指數方程','x 出現在右上角的次方位置，例如 2^(x + 1) = 8。',['先試把兩邊寫成同一個數的次方，例如把 8 寫成 2³。','底數相同，而且大於 0、不等於 1 時，右上角的次方必須相同，所以列 x + 1 = 3。','解完把 x 代回原式檢查。若不能方便地改成同底，再考慮用對數。'],'1 的任何次方都是 1，所以底數為 1 時，不能說兩邊次方一定相同。','2^(x + 1) = 2³：比較次方，得到 x + 1 = 3；再解這條一次方程。','指數'),
  method('指數與對數','定義與指數互換','log₂8 是問：「2 的幾次方等於 8？」這就是對數的意思。',['在 logₐb 裏，a 叫底數，必須大於 0 且不等於 1；b 叫真數，必須大於 0。','把 logₐb = c 換成 a^c = b，就是「a 的 c 次方等於 b」。','用熟悉的次方找答案，再代回原來的 log 式檢查。'],'log 不是兩個數相除；log 後面的數不能是 0 或負數。','log₂8 = 3，因為 2 × 2 × 2 = 8，也就是 2³ = 8。','對數'),
  method('指數與對數','合併與拆開對數','有幾個 log 相加、相減，或 log 前面乘了一個數。',['先看左下角的底數是否相同；每個 log 後面的數也要大於 0。','同底時，相加可把裏面的數相乘；相減則相除。例如 log₂6 − log₂3 = log₂(6/3)。','log 前面乘的數可變成裏面的次方，例如 2log₂3 = log₂(3²)。'],'log(a + b) 不能拆成 log a + log b；裏面是加法，不是乘法。','log₂3 + log₂4 = log₂(3 × 4) = log₂12。','對數'),
  method('指數與對數','方程與真數限制','log 後面的部分含 x，例如 log₂(x − 1)。這部分叫「真數」。',['每一個原來的 log 裏面都要大於 0。例如 x − 1 > 0，便先記下 x > 1。','把同底 log 合併；再用「log₂A = 3 就是 A = 2³」來改寫方程。','算出的 x 要逐個放回原來每個 log 裏面；令任何一個裏面變成 0 或負數的答案，都不能用。'],'兩個負數相乘也會是正數，所以只檢查合併後的乘積並不足夠。','log₂(x − 1) + log₂(x + 1) = 3：先記 x > 1，再列 (x − 1)(x + 1) = 8。','對數'),
  method('指數與對數','換底與代換','幾個 log 左下角的底數不同，或底數本身是 x，需要先改成同一種寫法。',['選一個共同底數，例如 2，要求它大於 0 而且不等於 1。','用 logₐb = log₂b / log₂a。若 log₂x 重複出現，可以暫叫它 u，式子就較短。','先求 u，再用 log₂x = u，也就是 x = 2^u，換回 x。最後檢查每個原底數大於 0、不等於 1。'],'換底後，原來的底數 a 放在分母的 log 裏，不是分子；每個 log 裏面的數也須大於 0。','設 u = log₂x，則 logₓ8 = log₂8/log₂x = 3/u；x > 0 且 x ≠ 1。','對數'),
  method('指數與對數','對數坐標與直線','圖上的軸寫着 log x 或 log y，表示刻度上的數已經是對數值。',['先把橫軸那整個 log 叫 X，縱軸那整個 log 叫 Y，當作普通直線圖處理。','用斜率 m 和一個圖上的點 (X₁,Y₁)，列 Y − Y₁ = m(X − X₁)。','把 X、Y 換回原來的 log。若底數不同先換底，再用對數規則改成 x、y 的關係。'],'圖上 X = 3 不代表 x = 3；例如 X = log₂x = 3，實際 x 是 8。','X = log₂x、Y = log₂y，若 Y = 3X + 1，就有 log₂y = log₂(x³) + log₂2，所以 y = 2x³，x > 0。','對數'),
  method('指數與對數','等比數列取對數','原數列每次乘同一個數，並且每一項都大於 0；現在要對每項取 log。',['先找第一項 a 和每次乘的數 r，寫第 n 項 ar^(n − 1)，a、r 都要大於 0。','對每項取相同底數的 log，便成 log a + (n − 1)log r。底數須大於 0、不等於 1。','新數列每次加的都是 log r，所以是等差數列。若要加總，要用新數列的第一項 log a 和公差 log r。'],'先取 log 再相加，不等於先把原來數列加起來再取 log。','原數列 1、2、4、8，取以 2 為底的 log，變成 0、1、2、3，每次加 1。','對數'),
  method('概率','列清樣本空間','題目問某件事發生的機會，即「概率」。全部可能結果合起來叫樣本空間。',['先列可能結果，看看每個結果的機會是否一樣。','若機會一樣，就用「符合題目要求的結果數 ÷ 全部結果數」。','抽選人或物件時，每人或每件都要計一次，重複的數值也不能合併。'],'只有各結果機會一樣，才可直接數結果再相除；不同類別不一定各佔一半。','公平骰子有 6 個結果，偶數是 2、4、6，共 3 個，所以概率 = 3/6 = 1/2。','樣本空間'),
  method('概率','至少一次用補事件','「至少一次」包括一次、兩次或更多。有時反過來算「一次也沒有」較快。',['先寫相反情況：例如至少一次正面，相反就是全部反面，這叫補事件。','算全部失敗的機會。只有每次互不影響，才可直接把各次失敗的概率相乘。','用 1 減去剛才的結果，便得到至少成功一次的機會。'],'「至少一次」不是「剛好一次」；兩次或更多也算。','公平硬幣獨立擲三次，全部反面的機會是 (1/2)³，所以至少一次正面是 1 − (1/2)³ = 7/8。','補事件'),
  method('概率','不放回逐次更新','抽出的物件不放回去，所以第二次可抽到的物件比第一次少。',['畫樹狀圖，先寫第一次各種結果的概率。','沿每條線，數清抽走甚麼、還剩多少。例如抽走一個紅球，紅球數和總數都減 1。','沿同一條完整路線把概率相乘；不同而符合要求的完整路線，再把概率相加。'],'題目要一紅一藍時，先紅後藍、先藍後紅都要計；第二次也不能用原來總數。','3 紅 2 藍，連抽兩個都紅：第一次 3/5，第二次剩 2 紅共 4 球，所以是 3/5 × 2/4。','不放回抽取'),
  method('概率','獨立與互斥分清楚','題目問兩件事一起發生，或其中至少一件發生。',['「獨立」是發生了 A，也不改變 B 的機會；只有這時，兩件一起發生的概率才可用 P(A) × P(B)。','「互斥」是兩件事不可能一起發生，例如一次擲骰子不會既是 2 又是 5。','求 A 或 B：先加 P(A) 和 P(B)，再減去兩件一起發生的概率，避免計兩次。'],'互斥不是獨立。兩件都有機會發生的事，若互斥，發生了一件就令另一件不可能發生。','一次擲骰子，「偶數」有 2、4、6，「大於 4」有 5、6；算其中至少一項成立時，6 只能計一次。','獨立與互斥'),
  method('幹葉圖與集中趨勢','讀鍵與還原數據','數字拆成左邊的「幹」和右邊的「葉」，要把兩邊合起來讀。',['先看圖旁的「鍵」，它會說明 2｜3 是 23 還是 2.3，不要自行猜。','每一片葉都是一筆資料。即使兩片葉的數字相同，也要數兩次。','把完整數值寫出來，按大小排好，再核對總共有多少筆。'],'不能只把葉的數字拿來算平均數；它還要配上左邊的幹。','鍵是 2｜3 = 23 時，幹 2 配葉 1、1、5，表示三個數：21、21、25。','幹葉圖'),
  method('幹葉圖與集中趨勢','總和與加權平均','平均數就是把總數平均分。表中的「頻數」是某個數值出現了多少次。',['一般用「全部加起來 ÷ 個數」。已知平均數時，也可反過來用「平均數 × 個數」求總和。','有頻數表時，每個數值先乘出現次數，再全部加起來，不用逐個抄出。','最後除以總個數。合併兩組資料時，要先把兩組的總和、人數分別加起來。'],'一組 3 人、一組 20 人，不能把兩組平均數直接相加再除以 2，因為人數不同。','3 人平均 10，2 人平均 15：總和是 3 × 10 + 2 × 15 = 60，共 5 人，平均數是 12。','平均數'),
  method('幹葉圖與集中趨勢','排序後找中間','中位數就是數據由小至大排好後，正中間的數。',['先由小至大排列，重複的數也照樣排，再數清共有多少個。','奇數個時，取正中間一個。例如 9 個數，取第 5 個。','偶數個時，中間有兩個，要把它們相加除以 2。例如 10 個數，取第 5、6 個的平均。'],'不要把「第幾個」當成答案；找出那個位置上實際的數值。','2、3、7、8 已排好，中間是 3 和 7，所以中位數 = (3 + 7)/2 = 5。','中位數'),
  method('幹葉圖與集中趨勢','由中位數反推頻數','已知中位數，但不知道某一組有多少人。',['把各組人數一路加下去，寫出每個數值排在第幾個至第幾個位置。','總人數若是奇數，中間只有一個；若是偶數，就看中間兩個的平均。兩種都要試。','找出哪些總人數會得到題目指定的中位數，再減去已知人數，求未知那組有多少人。'],'偶數人時，中間兩個數可以不同；只要它們的平均等於題目的中位數便可以。','若第 5、6 個都是 7，總數 9、10 或 11 時，中位數都可能是 7；還要檢查其他條件。','中位數'),
  method('幹葉圖與集中趨勢','比較出現次數','眾數就是出現次數最多的數值，可以不只一個。',['數一數每個數值出現多少次，這個次數叫頻數。','找出出現最多次的是哪個數值。','若幾個數值並列最多次，把它們全部寫下。'],'例如 5 出現 8 次，眾數是 5，不是 8；也不是數據中最大的那個數。','2、2、3、5、5：2 和 5 都出現兩次，並列最多，所以兩個都是眾數。','眾數'),
  method('圓形幾何','先圈出同弧與切線','圓裏有幾個角，或有一條只在一點碰到圓的切線，要找角度關係。',['沿每個角的兩邊，看它們碰到圓上的哪兩點；把相同的兩個端點圈出來。','再看角的位置：例如兩個圓周角在同一條弦的同一側，便是同弓形內的圓周角，相等。','用合適的圓定理找到角，再配合三角形三個角合共 180°，一步一步寫出理由。'],'不能只見端點相同就說角相等，還要看角在弦的哪一側；用切線定理也要先確認它真的是切線。','同一段弧所對的圓心角是 80°，相應圓周角是它的一半，即 40°。'),
  method('函數與圖像','由圖讀取關係','f(x) 可以看成一條計算規則：放進 x，算出 y。圖像畫出這些 x、y 配對。',['求 f(3) 就把規則裏每個 x 換成 3；f(3) 不是 f 乘 3。','找圖像碰到 x 軸的地方，令 y = 0；找碰到 y 軸的地方，令 x = 0，這些叫截距。','題目限制了 x 的範圍時，只看那一段圖像；找最大最小值還要留意轉彎點和兩端。'],'f(a + b) 是先把 a、b 相加再放入規則，一般不等於分開算 f(a)、f(b) 再相加。','f(x) = x² − 4：f(3) = 3² − 4 = 5；碰到 x 軸時 x² − 4 = 0，所以 x = ±2。'),
  method('平面三角學','對邊、鄰邊與斜邊','直角三角形已知角和邊，要用 sin、cos 或 tan 找另一個量。',['先圈出正在用的銳角：正對着它的是對邊，旁邊而又不是斜邊的是鄰邊；直角對面最長的是斜邊。','sin = 對邊/斜邊，cos = 鄰邊/斜邊，tan = 對邊/鄰邊。看看題目涉及哪兩邊，再選公式。','求角時，用計算機的 sin⁻¹、cos⁻¹ 或 tan⁻¹；題目以度數表示時，計算機要用 DEG 模式。'],'換了所用的角，對邊和鄰邊會對調；斜邊永遠是直角對面那條。','斜邊 10、角 30°，對邊/10 = sin30°，所以對邊 = 10sin30° = 5。','直角三角比'),
  method('平面三角學','角與對邊成對','不一定有直角，但已知一個角和它正對面的邊，可考慮正弦定理。',['把角 A 和它對面的邊 a 配好，角 B 和邊 b 也一樣配好。','用 a/sinA = b/sinB，把已知數值放進去，再求未知的邊或角。','求角時，計算機給出 θ，還要試 180° − θ 是否也可能；用三角形角和及其餘條件檢查。'],'已知兩邊和其中一邊的對角時，可能有兩個不同三角形，別只保留計算機給的第一個角。','A = 30°、對邊 a = 5，B = 60°，便列 b/sin60° = 5/sin30°。','正弦定理'),
  method('平面三角學','兩邊夾角或三邊','已知兩邊和它們中間的角，要找第三邊；或已知三邊，要找其中一個角。',['把要用的角記作 A，它對面的邊記作 a；夾着這個角的另兩邊是 b、c。','用餘弦定理 a² = b² + c² − 2bc cosA，把邊和角一一放對位置。','求邊時，算出 a² 後再開正平方根；求角時，先算 cosA，再用 cos⁻¹。最後才四捨五入。'],'A 一定要是 b、c 夾着的角；公式裏 −2bc cosA 整部分都不能漏。','兩邊 3、4，中間是 60°：第三邊平方 = 3² + 4² − 2 × 3 × 4 × cos60°。','餘弦定理'),
  method('平面三角學','兩邊與夾角求面積','三角形已知兩邊和它們中間的角，即使不知道高，也可以求面積。',['圈出那兩條邊 a、b，再確認角 C 正好夾在它們中間。','直接用面積 = a × b × sinC ÷ 2。','檢查長度單位相同、角度模式正確，答案用 cm² 等平方單位。'],'不是隨便選一個角都可以；用的角要在那兩條已知邊之間。','兩邊 6、8，夾角 30°：面積 = 6 × 8 × sin30° ÷ 2 = 12。','三角形面積'),
  method('框線圖與離差','讀五數摘要','框線圖用五個位置，讓你看出數據的中間在哪裏、散得多開。',['依刻度讀兩端的最小、最大值；框的左邊是 Q₁、右邊是 Q₃，框內的線是中位數。','比較中位數，看哪組的中間數值較大；比較框的長度，看中間一半資料哪組較分散。','如果問全部資料的範圍，就看最左至最右，不是只看框。'],'框畫得長，不代表人數較多；它表示數值之間的距離較大。','Q₁ = 12、Q₃ = 20，框長是 8，表示中間一半資料的範圍由 12 到 20。','框線圖'),
  method('框線圖與離差','最大值減最小值','分布域就是最大、最小兩個數相差多少，描述全部資料跨了多大範圍。',['先找實際出現的最小數和最大數。','用最大值減最小值，不是把兩者相加。','若缺少其中一個，用「最大值 − 最小值 = 分布域」倒過來求。'],'比較的是資料數值，不是出現次數；表裏沒有任何人出現的數值不能當最小或最大。','最小值 22、最大值 49，分布域 = 49 − 22 = 27。','分布域'),
  method('框線圖與離差','上下半部的中位數','四分位數間距是中間一半數據跨了多大範圍，用 Q₃ − Q₁ 表示。',['把數據由小至大排好，再按課堂採用的定位方式，分成下半部、上半部。','下半部中間的數是 Q₁，上半部中間的數是 Q₃。若有頻數表，先把人數加起來找位置。','用 Q₃ 減 Q₁。這次不是最大值減最小值，也不用再除以 2。'],'奇數筆資料時，先按課堂規則處理正中間那筆，不要兩種定位方式混用。','1、2、3、4、5、6、7、8：Q₁ = (2 + 3)/2，Q₃ = (6 + 7)/2，間距是 6.5 − 2.5 = 4。','四分位數間距'),
  method('一次方程','設未知數與列等式','有一個不知道的數量，題目給了它與其他數量的關係。',['先寫「設 x 為……」，例如每本書的價錢，單位是元。','同一個數量若有兩種寫法，就在它們中間放等號，例如 3 本書加 5 元等於 20 元。','等號兩邊做同一運算，逐步讓 x 單獨留下。算完放回題目檢查。'],'算出的 x 未必就是題目最後問的數量；若問 3 本書的價錢，還要乘 3。','3x + 5 = 20：兩邊減 5，得 3x = 15；兩邊除以 3，得 x = 5。'),
  method('一次不等式','移項與反轉不等號','像解方程一樣找 x，但符號是 >、<、≥ 或 ≤，答案通常是一段範圍。',['有括號就先乘開，再把含 x 的部分放在同一邊，數字放在另一邊。','兩邊乘或除以負數時，符號要反方向：< 變 >，≤ 變 ≥，反過來也一樣。','看有沒有等號：x < 3 不包括 3；x ≤ 3 則包括 3。可把範圍畫在數線上。'],'兩邊加減同一個數不會反方向；乘除正數也不會，乘除負數才會。','−2x < 6：兩邊除以 −2，< 變 >，所以 x > −3。','單一不等式'),
  method('一次不等式','及與連續不等式','題目寫「及」或「同時滿足」，意思是兩條要求都要做到。',['先分開解兩條不等式；例如 1 < 2x ≤ 6，拆成 1 < 2x 和 2x ≤ 6。','把兩個範圍畫在同一條數線上。','只留下兩段重疊的部分，這叫「交集」。完全沒有重疊，就沒有符合的數。'],'不能只符合其中一條；選一個數代回去時，兩條都要成立。','x > −2 及 x ≤ 3：要同時大於 −2、不大於 3，所以 −2 < x ≤ 3。','聯立不等式'),
  method('一次不等式','或與聯集','題目寫「或」，意思是只要符合其中一條就可以，兩條都符合也可以。',['分別解兩條不等式。','把兩個範圍都畫出來，任何一段包括的數都留下，這叫「聯集」。','若一段已完全包住另一段，只寫較大那段便足夠；若分開兩段，就兩段都寫。'],'不要只取重疊部分；那是「及」的做法。','x < 1 或 x ≥ 4：0 符合第一條、5 符合第二條，所以兩個都可以；2 則不可以。','或連接不等式'),
  method('一次不等式','界限附近找整數','題目要整數，即沒有小數部分的數，例如 −2、−1、0、1、2。',['先找符合不等式的範圍，看看最左、最右的界線本身能否包括。','按題目只留正整數、負整數或全部整數。求最大值，就由右邊附近的整數開始試。','把找到的數代回檢查。求最大整數時，再試大 1 的數，確認它已不符合。'],'負數越接近 0 越大，例如 −2 比 −3 大；0 既不是正整數，也不是負整數。','x < −2：−2 不可以，最接近它而又較小的整數是 −3，所以最大整數解是 −3。','整數解'),
  method('百分數','辨清比較基數','題目說「比某個數多 20%」或「少 20%」，要先知道是跟誰比較。',['圈出比較對象，把它當作完整的 1，也就是 100%。這個比較起點叫「基數」。','多 20%：原數 × (1 + 20%)；少 20%：原數 × (1 − 20%)。先寫出「原有的 1，加上或減去多少」，再計算，不用先心算成小數。','題目後半若換了比較對象，就重新決定誰是 1。要找回原數，用新數除以整個 (1 + 百分率) 或 (1 − 百分率)，且除數不能是 0。'],'A 比 B 多 20%，不代表 B 比 A 少 20%，因為兩句話的比較起點不同。','B 是 100，A 比 B 多 20%：A = 100 × (1 + 20%) = 120。倒過來看，B 比 A 少的是 (120 − 100)/120，不是 20/100。','百分比增減'),
  method('百分數','售價與標價互求','標價是價錢牌上的數字；售價是打折後實際付的錢。',['八折表示付原價的 80%，所以乘 0.8；七五折則乘 0.75。','已知標價：用標價 × 折扣的小數，求實際售價。','已知售價，想找回標價：反過來用除法，售價 ÷ 折扣的小數。'],'八折是付 80%，不是減去 80%；打折後的售價應比標價低。','八折後付 160 元：標價 = 160 ÷ 0.8 = 200 元。再用 200 × 0.8 檢查。','折扣'),
  method('百分數','成本、售價與盈虧','成本是買入或製作花的錢；售價是賣出收到的錢，兩者相減才知道賺或蝕。',['售價 − 成本：正數是賺錢，負數是蝕錢。盈利 20%：售價 = 成本 × (1 + 20%)；虧蝕 20%：售價 = 成本 × (1 − 20%)。','盈利率一般用「賺的錢 ÷ 成本 × 100%」；虧蝕率用「蝕的錢 ÷ 成本 × 100%」。','若先加價再打折，就先求標價、再求售價，最後與成本比較。'],'盈利 20% 是每 100 元成本賺 20 元，不是每 100 元售價賺 20 元。','成本 100 元，加價 50%：標價 = 100 × (1 + 50%) = 150 元。八折售價 = 150 × 80% = 120 元，賺 20 元，盈利率為 20%。','盈利與虧蝕'),
  method('百分數','單利與複利','本金是最初存入的錢，利息是多出來的錢，本利和是兩者合計。',['單利每次只按最初本金計息；複利會把先前利息也算進下一次。','本金 P、每期利率 r、共 n 期，單利合計 P(1 + nr)。例如利率 5%，便代 r = 5% = 0.05。','複利每期乘一次 (1 + r)，合計 P(1 + r)^n；若只問利息，還要減最初本金。'],'利率和期數要配合，年利率配年數，不能直接把年利率當月利率。','1000 元、每年 5%、兩年：單利是 1000 × (1 + 2 × 5%)；按年複利是 1000 × (1 + 5%)²。先列出增加 5% 的意思，再計算。','利息'),
  method('多項式與因式定理','代根求餘式','題目問多項式除以 x − a 剩多少，或說 x − a 是它的因式。',['先找令除式等於 0 的 x。例如 x − 2 = 0，就用 x = 2。','把它放入 f(x)。f(2) 就是除以 x − 2 的餘式；若能整除，結果要等於 0。','用所得等式求未知的數；若還要完整分解，再做長除法或繼續找因式。'],'除式是 x + 2，要代 −2，不是 2；先讓除式等於 0 就不易弄錯。','f(x) = x² + x − 6：f(2) = 4 + 2 − 6 = 0，所以除以 x − 2 沒有餘式。'),
  method('變分','正比先求常數','「y 與 x 成正比」表示 y 一直是 x 的同一倍數，那個倍數叫 k。',['成正比寫 y = kx；若與 x² 成正比，則寫 y = kx²。','用題目給的一組 x、y，先求 k 是多少。','之後 k 不變，把新的 x 或 y 放回同一條公式，求另一個量。'],'要跟着題目的次方；與 x² 成正比時，x 乘 2，y 是乘 4，不是乘 2。','y = kx²，x = 2、y = 12：12 = 4k，所以 k = 3，公式便是 y = 3x²。','正變'),
  method('變分','反比看乘積','「y 與 x 成反比」是 x、y 的乘積保持不變。正數情況下，x 越大，y 越小。',['寫 y = k/x，也就是 xy = k，x 不能是 0。若與 x² 成反比，分母要寫 x²。','用一組已知 x、y 相乘，找出固定的 k。','把新數值放回公式求另一個量，並檢查是否符合題目的次方。'],'反比不是 y = −kx；它是用 x 作除數，不是給正比公式加一個負號。','x = 3、y = 8，乘積是 24；當 x = 6，y = 24/6 = 4，x 加倍而 y 減半。','反變'),
  method('變分','部分變分分項列式','一個量分成幾部分，例如固定收費，加上按用量計的收費。',['把每一部分分開寫，再相加；每部分可有自己不同的固定倍數。','例如固定收費 a，每用一單位收 b，用了 x 單位，總額就是 y = a + bx。','把已知的兩組或更多資料代入，聯立求 a、b，再逐組放回檢查。'],'不要漏掉固定部分，也不要未有理由就認定兩部分的倍數相同。','x = 1 時 y = 5，x = 2 時 y = 8：多用一單位多收 3，所以 b = 3，再得 a = 2。','部分變分'),
  method('面積與體積','球體半徑與三次方','求球內的體積，或比較大小不同的兩個球佔多少空間。',['公式裏的 r 是半徑；題目給直徑時，先除以 2。','用體積 = 4πr³/3。半徑若乘 2，體積便乘 2³ = 8。','用比例分總體積時，先數共有幾份，再看每球佔幾份。'],'半徑放大幾倍，體積不是直接放大同樣倍數，要把倍數取三次方。','半徑比 1:2，體積比是 1:8，合共 9 份，大球佔總體積的 8/9。','體積'),
  method('面積與體積','球面積分球計算','求球外面整層的面積，公式是 4πr²，不是體積的 4πr³/3。',['先找半徑 r；若只給體積，先用體積公式求 r³，再開三次根找 r。','每個完整球分別算 4πr²，半徑放大 2 倍，面積就放大 4 倍。','若有幾個球，把各自面積加起來，單位用 cm² 等平方單位。'],'不能先把半徑相加再平方；球的外面也不只是一個平面圓，不能只用 πr²。','半徑 1、2 的兩球，面積分別是 4π、16π，相加是 20π。','表面積'),
  method('立體三角學','拆出平面直角三角形','立體圖內求高度、斜線長度，或斜線與平面的夾角。',['從上方的點向底面畫垂直線，落到的點叫垂足；連起斜線另一端與垂足，便得到底面的投影。','先在底面算投影多長，再把投影、垂直高、斜線抽出來畫成一個直角三角形。','線與平面夾角就是斜線與投影的夾角，再用畢氏定理或 sin、cos、tan。'],'不要隨便用底面一條邊代替投影；先找垂足，才知道正確的三角形。','垂直高 3、底面投影 4，斜線長 √(3² + 4²) = 5；夾角可用 tanθ = 3/4。'),
  method('標準差與標準分','平移與倍乘數據','每筆資料都加同一個數，或都乘同一個數，想知道平均數、標準差怎樣變。',['先寫「新數據 = a × 原數據 + b」，看清先乘多少、再加多少。','平均數也照樣做：新平均數 = a × 原平均數 + b。','標準差只乘 |a|，即 a 去掉負號後的大小。全部加 b，不會改變彼此的距離。'],'乘負數後，標準差也不能變負數；只有方差才乘 a²，標準差乘 |a|。','原標準差 4，每筆變成 −2x + 7，彼此距離放大 2 倍，所以新標準差是 8。','標準差'),
  method('標準差與標準分','由頻數表求標準差','標準差描述數據散得多開：越大，表示數據整體離平均數越遠。',['把每個數值 x 和出現次數 f 配好，先求總個數 N。不要把次數本身當成數值。','用計算機的統計功能輸入 x 和 f，求平均數及分布標準差 σ；手算可用 σ = √[Σfx²/N − (Σfx/N)²]，Σ 表示全部加起來。','有幾個可能的人數時，每種都重算，再比較結果；最後才四捨五入。'],'fx² 是先把 x 平方再乘次數 f，不是把 f 也平方。求分布標準差時，勿選除以 N − 1 的樣本標準差。','數據 1、3，平均是 2；兩個數都離平均 1，所以標準差是 1。','標準差'),
  method('標準差與標準分','相對平均數的位置','比較不同班或不同考試的成績時，不只看原分數，還要看它比該組平均高多少。',['找各組的平均數和標準差；標準差須大於 0，才能作分母。','用 z = (分數 − 平均數)/標準差，這叫標準分。','正的 z 表示高於平均，負的表示低於平均；z 越大，相對該組平均的位置越高。'],'不是分數較高就一定標準分較高，各組平均數和分散程度也會影響結果。','平均 60、標準差 5，考 70 分：z = (70 − 60)/5 = 2，即高於平均兩個標準差。','標準分'),
  method('組合','選取而不計次序','只選出一組人或物件，不分誰排先、誰排後。',['先問：「選 A、B」和「選 B、A」是否算同一組？若算同一組，就是不計次序。','從 n 個不同物件選 r 個，沒有其他限制時，用計算機的 nCr。','有指定條件時，分成互不重複的情況，例如選 1 男 1 女，再算每種情況有多少組。'],'選組員不分職位，不能用排列；選正、副班長，職位不同才要計次序。','5 人選 2 人做同一組，5C2 = 10；A、B 和 B、A 只計一組。'),
  method('頻數與累積頻數','組中值估算平均數','只知道每組的範圍和人數，不知道每個人的數值，所以只能估計平均數。',['先找每組中間的數，叫組中值。例如 10–19 的中間是 (10 + 19)/2 = 14.5。','用每組的組中值乘該組人數，再把全部結果加起來，估計總和。','把剛才的總和除以總人數，便是估計平均數。'],'每組人數可能不同，不能只把幾個組中值相加除以組數。','兩組的組中值是 5、15，各有 2、3 人：估計平均數 = (5 × 2 + 15 × 3)/(2 + 3) = 11。','頻數'),
  method('頻數與累積頻數','相減還原頻數','頻數是「這一組有多少個」；累積頻數是「從第一組到這裏，一共有多少個」。',['最後的累積數就是全部個數，記作 N。','想找單獨一組有多少個，用「加到這組的總數 − 加到上一組的總數」。','若要從曲線估計四分位數，就從直軸 N/4、N/2、3N/4 找到曲線，再向下讀橫軸的數值。'],'不要把所有累積數再相加，這會把同一批資料重複計算。','加到上一組共有 12 人，加到這組共有 20 人，所以這一組有 20 − 12 = 8 人。','累積頻數'),
  method('公式變換','逐層解開目標字母','轉主項口訣：「乘、拆、移、抽、除」。「以 x 為主項」就是改成 x = ……，右邊不再有 x。',[
    '乘：等號兩邊每一項都乘共同分母，去掉分母。拆：用括號外的數乘入括號內每一項，拆開括號；負號也要一起乘入。',
    '移：把含 x 的項集中在一邊，其餘項放到另一邊。移項變號，其實是等號兩邊同加或同減一項，不是把乘數隨便搬過去。',
    '抽：幾項都有 x，就把共同的 x 抽到括號外。除：兩邊除以乘着 x 的整個數或括號，讓 x 單獨留下；先確認除數不等於 0。'
  ],'沒有分母、括號或重複的 x，就跳過相應步驟，不用硬做齊五步。若有 x²、根號等，還要用相應運算解開，並檢查答案限制。','簡單例子 y = 3x + 2，只需「移、除」：兩邊減 2，得 y − 2 = 3x；再除以 3，得 x = (y − 2)/3。下面另有五步完整示範。'),
  method('二次不等式','根與符號區間','式子有 x²，題目問甚麼時候大於或小於 0，不是只問等於 0。',['先把一邊整理成 0，再暫用等號，找令式子等於 0 的 x，這些就是範圍的分界。','在數線標出分界，每段選一個數代入，看看結果是正還是負，也可畫拋物線判斷。','要 < 0 就留負的那段，要 > 0 就留正的。只有 ≤ 或 ≥，才包括令式子等於 0 的分界。'],'不要只寫兩個分界數；答案通常是一段或幾段 x 的範圍。','(x − 1)(x − 3) < 0：在 1 和 3 之間，兩括號一正一負，所以是 1 < x < 3。'),
  method('軌跡','把距離條件翻譯成圖形','一個點可以移動，但一直要符合某些要求；所有允許位置合起來就是軌跡。',['寫清楚要求，例如離 A 固定 3 cm，或離 A、B 一樣遠。','離 A 固定 3 cm 的位置圍成圓；離 A、B 一樣遠的位置，是穿過 AB 中點且與 AB 成直角的直線。','兩個條件都要符合，就找兩條軌跡相交的位置，再檢查是否在題目指定範圍內。'],'畫出一整條線後，還要看題目有沒有只限某區域，不能把區域外的位置也當答案。','離 A、B 一樣遠的點都在 AB 的垂直平分線上；AB 的中點也是其中一個。'),
  method('等差數列','固定差與項數','一串數每次加同一個數，例如 3、7、11……每次加 4。',['第一個數叫首項 a；「後一項減前一項」的固定結果叫公差 d，可以是負數。','由第 1 項到第 n 項，共走 n − 1 步，所以第 n 項 = a + (n − 1)d。','前 n 項和用「項數 × (第一項 + 最後一項) ÷ 2」，也就是 n[2a + (n − 1)d]/2。'],'第 5 項只比第 1 項多走 4 步，不是 5 步。','3、7、11……第 5 項 = 3 + 4 × 4 = 19；前 5 項和 = 5 × (3 + 19)/2 = 55。'),
  method('等比數列','固定比與次方','一串數每次乘同一個數，例如 2、6、18……每次乘 3。',['第一項叫 a，每次乘的數叫公比 r，用「後一項 ÷ 前一項」找出，前一項須非零。','由第一項到第 n 項乘了 n − 1 次，所以第 n 項 = ar^(n − 1)。','前 n 項和用 a(1 − r^n)/(1 − r)；r = 1 時每項相同，直接用 na。'],'無限項的和不能隨便套公式；只有 −1 < r < 1，才可用 a/(1 − r)。','2、6、18……第 4 項是 2 × 3 × 3 × 3 = 54，即 2 × 3³。'),
  method('全等三角形','找三組足夠條件','全等就是兩個三角形形狀、大小都相同，可以完全疊在一起。',['先把已知相等的邊和角配成一對，頂點次序也跟着配好。','看條件：SSS 是三邊；SAS 是兩邊及中間的角；ASA 是兩角及中間的邊；AAS 是兩角及另一邊；RHS 是直角、斜邊及另一邊。','寫出符合哪個理由，證明全等後，才可說其餘相同位置的邊或角也相等。'],'只知三個角相同，大小仍可能不同；只知兩邊和一個不是夾在中間的角，一般也不足夠。','兩邊都是 3、4，中間的角都是 60°，便符合「兩邊及夾角」SAS。'),
  method('平面幾何角關係','找平行與角和','圖中有平行線或三角形，已知一些角，要一步步找另一個角。',['標出題目明說平行的線和已知角，不要只憑圖畫看起來平行。','一條線穿過兩條平行線時，同位角相等、內錯角相等；同旁內角相加是 180°。先按位置配好角。','再用一直線上的鄰角合共 180°、三角形內角合共 180° 等關係，找剩下的角。'],'內錯角要有平行線條件才可說相等；每一步寫出用了哪個理由。','三角形兩角是 50°、60°，第三角就是 180° − 50° − 60° = 70°。'),
  method('近似值與誤差','從取位找界限','量度值已四捨五入，真正數值可能稍大或稍小，需要找可能範圍。',['看取到哪一位：最近 0.1，表示相鄰記錄相差 0.1；它的一半是 0.05。','對以四捨五入記錄的正量，最低是記錄減半格，包括；最高是記錄加半格，不包括。','若還要算面積、重量等，先統一單位，再按題目求最大的情況或最小的情況。'],'取至最近 0.1，左右各留 0.05，不是 0.1；上界不包括，因為會進到下一格。','3.2 cm 取至最近 0.1 cm，真正長度是 3.15 ≤ 長度 < 3.25。','誤差界限'),
  method('近似值與誤差','上捨入與下捨入','題目指定向上或向下取近似值，不是四捨五入。這裏處理正數。',['看保留的位置，例如百位就是在 100、200、300……之間選。','上捨入選原數上方最近的那一格；下捨入選下方最近的那一格。若剛好在格上，數值不變。','檢查上捨入沒有變小、下捨入沒有變大，並確定保留了指定的位置。'],'下一位是否 5 或以上，在這題不決定方向；方向已由「上／下」指定。','234 在 200 和 300 之間；到百位，上捨入是 300，下捨入是 200。','取近似值'),
  method('近似值與誤差','小數位四捨五入','題目要幾位小數，就是要小數點後保留幾個數字。',['從小數點後開始數，圈出最後要保留的一位。','看緊接下一位：0–4 不進位，5–9 把最後保留位加 1，後面不再寫。','若尾數是 0，也要保留，讓人看出已做到題目要求的小數位。'],'不要從第一個非零數字開始數，那是有效數字的做法。','2.346 要兩位小數：保留到 4，下一位是 6，所以變 2.35；2.3 要兩位則寫 2.30。','取近似值'),
  method('近似值與誤差','有效數字定位','有效數字由第一個不是 0 的數開始數，不一定從小數點後開始。',['跳過最前面的 0，從第一個非零數字算第 1 位；之後的 0 也要計。','數到題目要保留的一位，再看下一位是否要四捨五入。','若去掉整數部分的數字，要用 0 補回位置，不能讓原數突然縮小幾十倍。'],'0.0045 開頭的 0 只是標示位置，不是有效數字；但 4 和 5 都是。','4567 要兩位有效數字：保留 4、5，下一位 6 要進位，所以是 4600，不是 46。','取近似值'),
  method('比與比例','用共同倍數表示','比例表示兩邊各有多少份，而且每份大小相同，例如 2:3 是一邊 2 份、一邊 3 份。',['把每份叫 k，兩個量就寫成 2k、3k，保持題目的前後次序。','題目給總數就相加，給相差就相減，用這條等式找每份 k 是多少。','再乘回份數，回答實際數量；比較比例前先把單位換成相同。'],'2:3 不代表第一部分佔全體 2/3；全體是 5 份，所以佔 2/5。','40 按 2:3 分：共 5 份，每份 8，兩部分便是 16、24。'),
  method('反射對稱','對稱軸是垂直平分線','把圖形沿一條線對摺或照鏡，兩邊能重合，這條線就是對稱軸。',['找作為鏡子的那條線，看看原來的點在它哪一側。','從原來的點向軸畫垂直線，再到另一側走同樣距離，得到反射後的點。','逐點處理並配好頂點；在軸上的點不用移動。'],'「原來的點」不一定是坐標原點 (0,0)；反射也不一定同時改變兩個坐標的符號。','(2,−3) 關於 y 軸反射：左右倒轉，上下不變，所以是 (−2,−3)。'),
  method('代數分式','分解再通分','分數的分母有字母。加減時，跟普通分數一樣，要先令分母相同，這叫通分。',['先看哪些字母值會令原分母變成 0，這些值不能用。','找共同分母。每個分數的分母乘了甚麼，分子也要乘同一個數或式子。','分母相同後，才把分子相加減。約分時，只能約去分子、分母整體共有的乘數。'],'例如 (x + 2)/x 不能劃掉 x，因為上面是 x 加 2；但 x(x + 2)/x 就可以約去共同乘數 x。','1/x + 1/(2x)：第一個分數上下都乘 2，變成 2/(2x)，相加便是 3/(2x)，x ≠ 0。'),
  method('坐標變換','分開處理兩個坐標','平移就是整個點向左、右、上或下搬動，不是旋轉或反射。',['x 管左右，y 管上下，先看題目移動哪個方向。','右移就在 x 加，左移就在 x 減；上移就在 y 加，下移就在 y 減。','沒有移動的方向保持不變；畫點看看方向是否與題目一致。'],'向上移只改 y，不改 x；也不要把兩個位置交換。','(1,2) 右移 3、下移 1：x = 1 + 3，y = 2 − 1，得到 (4,1)。','平移'),
  method('坐標變換','對稱軸與等距','把一個點當成在鏡中反射，鏡子可能是 x 軸、y 軸或 y = x。',['認清是哪一條反射軸，不能三條都用同一規則。','x 軸反射是上下倒轉，變 (x,−y)；y 軸是左右倒轉，變 (−x,y)；y = x 則兩個坐標交換，變 (y,x)。','檢查原來的點和反射後的點，到鏡線的垂直距離是否相同。'],'兩個坐標同時變號，一般是繞原點轉半圈，不是關於 x 軸或 y 軸反射。','(2,−3) 關於 x 軸反射：x 不變，y 變號，所以是 (2,3)。','反射'),
  method('坐標變換','順時針與逆時針','題目指定繞原點 (0,0) 轉四分一圈或半圈，方向要先看清。',['圈出旋轉中心及方向；以下規則只直接用於中心是原點。','由 (x,y) 出發，逆時針 90° 變 (−y,x)，順時針 90° 變 (y,−x)，180° 變 (−x,−y)。','在四個象限畫小草圖，看點是否轉到正確那一區，離原點的距離應不變。'],'順時針和逆時針的負號位置不同；已有負數時，再加負號會變正數。','(2,3) 順時針 90°，按 (y,−x) 得 (3,−2)，由右上方轉到右下方。','旋轉'),
  method('極坐標','距離與方向角','(r,θ) 不是左右、上下的坐標，而是「離中心多遠、朝哪個方向」。',['r 是離極點的距離，θ 是方向角；先看 0° 從哪條線開始、往哪邊量。','一般以向右為 0°、逆時針量角時，用 x = r cosθ、y = r sinθ 換成左右、上下坐標。','反過來，先用 r = √(x² + y²) 求距離，再看點在四個象限的哪一區，決定方向角。'],'只按 tan⁻¹(y/x) 可能選錯象限；x = 0 時也不能直接做這個除法。','(2,90°) 表示由中心向上走 2，所以直角坐標是 (0,2)。'),
  method('排列','位置不同算不同','選人或物件之後，還要安排不同位置或職位，換位就算不同結果。',['先列出要填的每個位置，例如正班長、副班長。','一人不能兼兩職時，選了第一人，第二個位置的選擇就少一個；依次把選擇數相乘，也可用 nPr。','有指定位置的條件先處理，再安排剩下的位置；分類時別把同一安排計兩次。'],'這個算法把物件視作不同；若有完全相同物件，交換後不能照樣當新排列。','5 人選正、副班長：正班長有 5 選擇，副班長剩 4，所以共 5 × 4 = 20。'),
  method('圓形圖','角度對應比例','圓形圖把全體分成幾塊，每塊角度越大，代表所佔比例越大。',['整個圓 360° 代表全部人數或數量。','某塊佔的比例 = 它的角度 ÷ 360°，再乘總數就得那一類有多少。','反過來已知人數，用「該類人數 ÷ 總人數 × 360°」求角度。'],'90° 不是 90%；角度要先除以 360°，才是比例。','90° 佔全圓 90/360 = 1/4，也就是 25%；全體 40 人時，這一類有 10 人。'),
  method('線性規劃','先畫可行區域','有幾項限制，例如材料和時間有限，要找最大的盈利或最少的成本。',['把限制逐條寫成不等式；數量不能為負時，也要寫 x ≥ 0、y ≥ 0。','把每條限制允許的範圍畫出，只留全部都符合的區域，叫可行區域。','若它是封閉、有界的多邊形，且目標是一次式，可把各角點代入比較；若限定整數，還要另查整數點。'],'區域可能沒有重疊或向外無限延伸；不能未檢查就認定一定有最大值。','x ≥ 0、y ≥ 0、x + y ≤ 4，三個角點是 (0,0)、(4,0)、(0,4)，代入 2x + y 後比較。'),
  method('速率與行程','時間單位先一致','已知走了多遠、用了多久、每小時多快，或比較兩人的行程。',['先把時間、距離單位配好，再用「路程 = 速率 × 時間」。','若分幾段行程，把每段的路程、時間各自列出，再求總和。','平均速率是「全部路程 ÷ 全部時間」，不是直接把幾個速率平均。'],'km/h 要配小時；30 分鐘要換成 0.5 小時，不能當 30 小時。','先走 60 km 用 1 h，再走 40 km 用 1 h；總路程 100、總時間 2，平均速率是 50 km/h。'),
  method('旋轉對稱','最小重合角','把圖形繞某點轉動，轉了之後又跟原圖完全重合。',['先找旋轉中心，想像整個圖形繞它轉。','找第一次重新重合時轉了多少度，必須大於 0°。','用 360° 除以這個最小角，就知道一圈會重合幾次，這叫旋轉對稱級數。'],'對摺的對稱軸和轉動的對稱級數是不同概念，不要直接當成相同。','正五邊形每轉 72° 便重合，一圈 360/72 = 5 次，級數是 5。'),
  method('期望值','每個結果乘概率','結果每次可能不同，想知道長期重複下來，平均一次可得多少分或多少錢。',['列出每種可能結果，以及它出現的機會。','檢查所有概率加起來等於 1，確認沒有漏掉某種結果。','每個結果乘自己的概率，再全部加起來；若問淨收益，還要扣每次固定付出的費用。'],'期望值是長期平均，不代表每次都會拿到這個數，甚至可能沒有一次剛好拿到它。','1/4 機會得 8 分，3/4 得 0 分，期望值 = 8 × 1/4 + 0 × 3/4 = 2 分。'),
  method('複數','用 i² = −1 化簡','式子有 i，要記住 i² = −1，不能把 i 當成普通實數。',['把沒有 i 的項合在一起，含 i 的項合在一起，目標寫成 a + bi；a、b 都是實數。','相乘時像代數括號一樣乘開，再把每個 i² 換成 −1。','相除時，分子分母同乘分母的共軛，即把 a + bi 改成 a − bi，令分母不再有 i；原分母不能是 0。'],'i² 是 −1，不是 1；分母乘了甚麼，分子也要乘同樣的式子。','(1 + i)(1 − i) = 1 − i² = 1 − (−1) = 2。')
];

